// --- 1. PREPARACIÓN DE DATOS Y CÁLCULOS ---
// Este bloque es clave para asegurar que no aparezcan valores nulos
// y para calcular los importes de IVA y el total.

const IVA_RATE = 0.21; // 21% de IVA estándar en España
let subtotal = 0;
let tableRow = '';

// Verificamos si hay un producto para calcular los totales.
// Usamos el precio del input para asegurar consistencia.
if ($json.producto && $json.precio) {
    const precioStr = ($json.precio || '0').toString().replace('€', '').replace('.', '').replace(',', '.');
    const precioNum = parseFloat(precioStr) || 0;
    const cantidad = parseInt($json.cantidad, 10) || 1;
    subtotal = precioNum * cantidad;

    tableRow = `
        <tr>
            <td>${$json.producto}</td>
            <td>${cantidad}</td>
            <td>${precioNum.toFixed(2).replace('.', ',')} €</td>
            <td>${subtotal.toFixed(2).replace('.', ',')} €</td>
        </tr>
    `;
}

// Calculamos el IVA y el total final
const iva = subtotal * IVA_RATE;
const totalFinal = subtotal + iva;

