//================================================================
//   EXTRACTOR UNIVERSAL DE FACTURAS v4.2 - DOMICILIO MEJORADO
//   Extracción precisa y robusta campo por campo
//================================================================

// --- 1. OBTENCIÓN DEL INPUT ---
const inputRaw = $input.first().json.text || "";

// --- 2. FUNCIONES AUXILIARES PRECISAS ---

function cleanText(text) {
    if (typeof text !== 'string' || !text) return null;
    return text
        .replace(/\*+|_+|#{1,6}\s*/g, '')
        .replace(/---+/g, '')
        .replace(/\s+/g, ' ')
        .trim();
}

function extractSingleLine(text, labels) {
    for (const label of labels) {
        const pattern = new RegExp(`${label}\\s*[:：]?\\s*([^\\n]+)`, 'i');
        const match = text.match(pattern);
        if (match && match[1]) {
            const cleaned = cleanText(match[1]);
            if (cleaned && !/Dirección|Correo|Email|Teléfono/i.test(cleaned)) {
                return cleaned;
            }
        }
    }
    return null;
}

// ================================================================
//   FUNCIÓN DE EXTRACCIÓN DE DOMICILIO MEJORADA Y REENTRENADA
// ================================================================
function extractAddress(text) {
    // 1. Acepta múltiples etiquetas posibles para la dirección.
    const labels = ['Dirección del cliente', 'Dirección fiscal', 'Domicilio', 'Dirección'];

    // 2. Define una lista exhaustiva de terminadores que marcan el final del bloque.
    const terminators = [
        'Correo electrónico', 'Correo', 'Email', 
        'Teléfono', 'NIF', 'CIF', 'DNI', 
        'Motivo', 'Concepto', 'Detalles de la Factura', 
        '---', 
        '\\n\\s*\\n' // Un doble salto de línea (línea en blanco) es un terminador clave.
    ];

    const terminatorsRegex = terminators.join('|');

    for (const label of labels) {
        // 3. El patrón ahora permite que la dirección empiece en la misma línea o en la siguiente (\s*\n?).
        //    Captura todo (.*?) hasta que ve uno de los terminadores (lookahead ?=).
        //    La bandera 's' (dotAll) permite que '.' capture también los saltos de línea.
        const pattern = new RegExp(`${label}\\s*[:：]?\\s*\\n?(.*?)(?=${terminatorsRegex})`, 'is');

        const match = text.match(pattern);

        if (match && match[1]) {
            const address = match[1].trim();
            if (address) {
                // 4. Limpia los saltos de línea internos y devuelve un string uniforme.
                return address.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
            }
        }
    }

    return null; // Si no encuentra ninguna dirección.
}

function extractComments(text) {
    const pattern = /Comentarios\s*[:：]?\s*\n?([^]*)/i;
    const match = text.match(pattern);
    if (match && match[1]) {
        const cleaned = cleanText(match[1]);
        if (cleaned) {
            return cleaned;
        }
    }
    return null;
}

function extractProduct(text) {
    const patterns = [
        /Motivo\s*[:：]?\s*([^\n]+)/i,
        /Concepto\s*[:：]?\s*([^\n]+)/i,
        /Descripción\s*[:：]?\s*([^\n]+)/i,
        /Servicio\s*[:：]?\s*([^\n]+)/i
    ];
    for (const pattern of patterns) {
        const match = text.match(pattern);
        if (match && match[1]) {
            let product = cleanText(match[1]);
            if (product) {
                return product.replace(/\.$/, '').trim();
            }
        }
    }
    return null;
}

function extractPrice(text) {
    const pricePattern = /Precio\s*[:：]?\s*([^\n]+)/i;
    const priceMatch = text.match(pricePattern);
    if (priceMatch && priceMatch[1]) {
        const priceLine = priceMatch[1];
        const numberMatch = priceLine.match(/([0-9]{1,3}(?:\.[0-9]{3})*(?:,[0-9]{1,2})?|[0-9]+(?:[.,][0-9]+)?)/);
        if (numberMatch && numberMatch[0]) {
            let numberStr = numberMatch[0].replace(/\./g, '').replace(',', '.');
            const parsed = parseFloat(numberStr);
            if (!isNaN(parsed) && parsed > 0) {
                return parsed;
            }
        }
    }
    return null;
}

// --- 3. PROCESAMIENTO PRINCIPAL ---
const inputText = $input.first().json.text || "";

const output = {
    "Fecha": new Date().toISOString().slice(0, 10),
    "numero_factura": `F-${new Date().getFullYear()}-${Date.now()}-${Math.random().toString(36).substring(2, 8).toUpperCase()}`,
    "fecha_emision": new Date().toISOString().slice(0, 10),
    "vencimiento": new Date(new Date().setDate(new Date().getDate() + 30)).toISOString().slice(0, 10),
    "cliente": null,
    "domicilio": null,
    "nif": null,
    "telefono": null,
    "comentarios": null,
    "email": null,
    "aplica_iva": "Si",
    "producto1": null,
    "cantidad1": 1,
    "precio1": null
};

// --- 4. EXTRACCIÓN CAMPO POR CAMPO ---
output.cliente = extractSingleLine(inputText, ['Factura para', 'Cliente', 'Razón social']);
output.domicilio = extractAddress(inputText);
output.email = (inputText.match(/[\w\.-]+@[\w\.-]+\.\w+/) || [])[0] || null;
output.telefono = extractSingleLine(inputText, ['Número de teléfono', 'Teléfono']);
output.nif = extractSingleLine(inputText, ['NIF', 'CIF', 'DNI']);
output.producto1 = extractProduct(inputText);
output.precio1 = extractPrice(inputText);
output.comentarios = extractComments(inputText);

// --- 5. FALLBACKS Y VALIDACIONES ---
if (!output.producto1 && output.precio1) {
    output.producto1 = "Servicios profesionales";
}
if (!output.comentarios && output.producto1) {
    output.comentarios = `Servicio de "${output.producto1}" realizado según lo acordado.`;
}
if (/(?:sin iva|exento|0% iva)/i.test(inputText)) {
    output.aplica_iva = "No";
}

// --- 6. RETORNO ---
return {
    json: output
};
